// DecodeEventsRequest returns a decoder for requests sent to the capability
// events endpoint.
func DecodeEventsRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*capability.EventsPayload, error) {
	return func(r *http.Request) (*capability.EventsPayload, error) {
		var payload *capability.EventsPayload
		var (
			limit  int
			cookie string
			err    error
		)
		{
			limitRaw := r.URL.Query().Get("limit")
			if limitRaw == "" {
				limit = 30
			} else {
				v, err2 := strconv.ParseInt(limitRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("limit", limitRaw, "integer"))
				}
				limit = int(v)
			}
		}
		if limit < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 1, true))
		}
		if limit > 100 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 100, false))
		}
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewEventsPayload(limit, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

