// marshalCapabilityCapabilityContractToCapabilityContractResponse builds a
// value of type *CapabilityContractResponse from a value of type
// *capability.CapabilityContract.
func marshalCapabilityCapabilityContractToCapabilityContractResponse(v *capability.CapabilityContract) *CapabilityContractResponse {
	res := &CapabilityContractResponse{
		Name:         v.Name,
		Version:      v.Version,
		Title:        v.Title,
		Description:  v.Description,
		Domain:       v.Domain,
		Entity:       v.Entity,
		Permission:   v.Permission,
		Risk:         v.Risk,
		Approval:     v.Approval,
		Idempotent:   v.Idempotent,
		ReadOnly:     v.ReadOnly,
		Executor:     v.Executor,
		Layer:        v.Layer,
		Kind:         v.Kind,
		Effect:       v.Effect,
		RetrySafe:    v.RetrySafe,
		InputSchema:  v.InputSchema,
		OutputSchema: v.OutputSchema,
	}
	if v.Reads != nil {
		res.Reads = make([]string, len(v.Reads))
		for i, val := range v.Reads {
			res.Reads[i] = val
		}
	}
	if v.Writes != nil {
		res.Writes = make([]string, len(v.Writes))
		for i, val := range v.Writes {
			res.Writes[i] = val
		}
	}
	if v.Tags != nil {
		res.Tags = make([]string, len(v.Tags))
		for i, val := range v.Tags {
			res.Tags[i] = val
		}
	} else {
		res.Tags = []string{}
	}
	if v.SuccessEvents != nil {
		res.SuccessEvents = make([]string, len(v.SuccessEvents))
		for i, val := range v.SuccessEvents {
			res.SuccessEvents[i] = val
		}
	} else {
		res.SuccessEvents = []string{}
	}

	return res
}

